colors=[2,3,4,6,7]
rows=[]
for band,c in enumerate(colors):
    for pattern in ([0,0,c,0],[c,c,c,c],[0,c,c,0],[0,0,c,0]):
        row=[]
        for col in range(5):
            if col: row.append(5)
            row.extend(pattern)
        rows.append(row)
    if band<4: rows.append([5]*24)
print(len(rows), [len(r) for r in rows])
import json
print(json.dumps(rows))
